import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';
import { compileSource } from '../tools/browser-toolchain.mjs';
import { ControlRuntime } from '../runtimes/wasm/control-runtime.mjs';

const wasm = () => fs.readFileSync(new URL('../target/wasm32-unknown-unknown/release/ghostflow_wasm.wasm', import.meta.url));
const document = code => `# Virtual control\n\nThe GhostFlow source below is the complete reviewed program.\n\n\`\`\`ghost\n${code}\n\`\`\`\n`;
const compile = (source, filename) => compileSource(source, { filename });

test('consumer framed WASM executes named VFD Number I/O and independent Start/Stop oracles', async t => {
  const source = document(`control VfdSpeed {
  input start, stop: Bool;
  input potentiometer_v: Number;
  output run: Bool;
  output speed_v, speed_hz: Number;
  state running: Bool = false;
  running' = if stop then false else if start then true else running;
  run <- running';
  speed_v <- potentiometer_v;
  speed_hz <- potentiometer_v * 5;
}`);
  const artifact = await compile(source, 'consumer-vfd.ghost.md');
  assert.deepEqual(artifact.manifest.inputs, [
    { name: 'start', type: 'Bool' }, { name: 'stop', type: 'Bool' },
    { name: 'potentiometer_v', type: 'Number' },
  ]);
  assert.deepEqual(artifact.manifest.outputs, [
    { name: 'run', type: 'Bool' }, { name: 'speed_v', type: 'Number' },
    { name: 'speed_hz', type: 'Number' },
  ]);
  const runtime = await ControlRuntime.instantiateFramed(wasm(), artifact);
  t.after(() => runtime.dispose());
  const frames = [
    [0, false, false, 0, false, 0, 0],
    [1, true, false, 5, true, 5, 25],
    [2, false, false, 10, true, 10, 50],
    [3, true, true, 5, false, 5, 25],
    [4, false, false, 10, false, 10, 50],
    [5, true, false, 0, true, 0, 0],
    [6, false, true, 5, false, 5, 25],
  ];
  for (const [nowMs, start, stop, potentiometer_v, run, speed_v, speed_hz] of frames) {
    const actual = runtime.step({ nowMs, inputs: { start, stop, potentiometer_v } });
    assert.deepEqual(actual.frame, { scanId: nowMs, logicalTimeMs: nowMs });
    assert.deepEqual(actual.vm.safe, { run, speed_v, speed_hz });
  }
});

test('consumer framed WASM also executes unrelated named Number and Boolean cabinet programs', async t => {
  const temperature = await compile(document(`control Temperature {
  input enabled: Bool;
  input temperature_c: Number;
  output fan: Bool;
  output observed_c: Number;
  fan <- enabled && temperature_c > 30;
  observed_c <- temperature_c;
}`), 'consumer-temperature.ghost.md');
  const temperatureRuntime = await ControlRuntime.instantiateFramed(wasm(), temperature);
  t.after(() => temperatureRuntime.dispose());
  for (const [nowMs, enabled, temperature_c, fan] of [
    [0, false, 25, false], [1, true, 35, true], [2, false, 40, false],
  ]) {
    const actual = temperatureRuntime.step({ nowMs, inputs: { enabled, temperature_c } });
    assert.deepEqual(actual.vm.safe, { fan, observed_c: temperature_c });
  }

  const cabinet = await compile(document(`control Cabinet {
  input DI1, DI2, DI3, DI4, DI5, DI6, DI7, DI8: Bool;
  output RO1, RO2, RO3, RO4, RO5, RO6, RO7, RO8: Bool;
  state running: Bool = false;
  running' = if DI2 then false else if DI1 then true else running;
  RO1 <- running';
  RO2 <- false; RO3 <- false; RO4 <- false; RO5 <- false;
  RO6 <- false; RO7 <- false; RO8 <- false;
}`), 'consumer-cabinet.ghost.md');
  const cabinetRuntime = await ControlRuntime.instantiateFramed(wasm(), cabinet);
  t.after(() => cabinetRuntime.dispose());
  const zero = Object.fromEntries(Array.from({ length: 8 }, (_, at) => [`DI${at + 1}`, false]));
  for (const [nowMs, DI1, DI2, run] of [
    [0, false, false, false], [1, true, false, true],
    [2, true, true, false], [3, false, false, false],
  ]) {
    const actual = cabinetRuntime.step({ nowMs, inputs: { ...zero, DI1, DI2 } });
    assert.deepEqual(actual.vm.safe, { RO1: run, RO2: false, RO3: false, RO4: false,
      RO5: false, RO6: false, RO7: false, RO8: false });
  }
});

test('consumer framed settings atomically apply Bool, Number, Percent and Duration without restarting', async t => {
  const source = document(`control LiveSettings {
  input start, stop: Bool;
  config enabled: Bool = true { access = operator; }
  config gain: Number = 1 { min = 0; max = 10; step = 1; access = operator; }
  config level: Percent = 20% { min = 0%; max = 100%; step = 10%; access = operator; }
  config duration: Duration = 5s { min = 1s; max = 10s; step = 1s; access = operator; }
  config untouched: Bool = false { access = operator; }
  state running: Bool = false;
  timer age = elapsed(running);
  running' = if stop then false else if start then true else running;
  output run, permitted: Bool;
  output gain_value: Number;
  run <- running' && case enabled { ok(value) => value; fault(_) => false; }
    && case duration { ok(value) => age < value; fault(_) => false; };
  permitted <- case level { ok(value) => value >= 30%; fault(_) => false; };
  gain_value <- case gain { ok(value) => value; fault(_) => 0; };
}`);
  const artifact = await compile(source, 'consumer-settings.ghost.md');
  assert.equal(artifact.manifest.format, 'GhostFlow/control-v10');
  assert.deepEqual(artifact.manifest.configs.map(item => [item.name, item.type]), [
    ['enabled', 'Bool'], ['gain', 'Number'], ['level', 'Percent'],
    ['duration', 'Duration'], ['untouched', 'Bool'],
  ]);
  const runtime = await ControlRuntime.instantiateFramed(wasm(), artifact,
    { context: { bootEpoch: 11, terminalCapacity: 8, bindings: [] } });
  t.after(() => runtime.dispose());
  const initial = runtime.contextSnapshot();
  const fingerprint = initial.state.programFingerprint;
  const ids = Object.fromEntries(artifact.manifest.configs.map(item => [item.name, item.id]));
  const change = (name, type, value) => ({ configId: ids[name], result: { ok: true, type, value } });
  const packet = (eventId, baseRevision, position, changes) => ({
    programFingerprint: fingerprint, eventId, baseRevision, position,
    origin: 'operatorEdit', changes,
  });
  const facts = (nowMs, settings = null) => ({
    clock: { monotonicMs: nowMs, bootEpoch: 11, wallMs: nowMs, uncertaintyMs: 0,
      trusted: true, unknownReason: null, sourceRevision: 'consumer-clock-v1' },
    natural: [], schedules: [], settings,
  });
  const scan = (nowMs, start, stop, settings = null) => runtime.step({
    nowMs, inputs: { start, stop }, contextFacts: facts(nowMs, settings),
  });
  const first = scan(0, true, false);
  assert.deepEqual(first.frame, { scanId: 0, logicalTimeMs: 0 });
  assert.deepEqual(first.vm.safe, { run: true, permitted: false, gain_value: 1 });
  const setup = scan(1, false, false, packet('untouched-on', 0, 2,
    [change('untouched', 'Bool', true)]));
  assert.deepEqual(setup.frame, { scanId: 1, logicalTimeMs: 1 });
  const before = runtime.contextSnapshot();
  assert.deepEqual(before.state.settings.find(item => item.name === 'untouched').result,
    { ok: true, value: true });
  const valid = packet('all-types', 1, 3, [
    change('enabled', 'Bool', true), change('gain', 'Number', 3),
    change('level', 'Percent', 40), change('duration', 'Duration', 2_000),
  ]);
  const edited = scan(1_000, false, false, valid);
  assert.deepEqual(edited.frame, { scanId: 2, logicalTimeMs: 1_000 });
  assert.deepEqual(edited.vm.safe, { run: true, permitted: true, gain_value: 3 });
  assert.equal(runtime.contextSnapshot().state.settingsRevision, 2);
  assert.equal(runtime.contextSnapshot().state.settings.find(item => item.name === 'untouched').result.value, true);
  assert.equal(runtime.manifest.bytecodeSha256, artifact.manifest.bytecodeSha256);
  assert.equal(artifact.sourceDocument.text, source);

  assert.throws(() => scan(1_500, false, false,
    packet('stale', 1, 4, [change('gain', 'Number', 4)])), /stale|settings transaction/i);
  assert.equal(runtime.contextSnapshot().state.settingsRevision, 2);
  assert.equal(runtime.lastFrameOutcome.scanId, 2);

  const invalid = scan(1_500, false, false, packet('invalid-aggregate', 2, 4, [
    change('enabled', 'Bool', false), change('gain', 'Number', 11),
    change('level', 'Percent', 50), change('duration', 'Duration', 3_000),
  ]));
  assert.deepEqual(invalid.frame, { scanId: 3, logicalTimeMs: 1_500 });
  assert.deepEqual(invalid.vm.safe, { run: false, permitted: false, gain_value: 0 });
  const faulted = runtime.contextSnapshot();
  assert.equal(faulted.state.settingsRevision, 3);
  for (const name of ['enabled', 'gain', 'level', 'duration']) {
    assert.deepEqual(faulted.state.settings.find(item => item.name === name).result,
      { ok: false, fault: 'SettingsInvalid' });
  }
  assert.deepEqual(faulted.state.settings.find(item => item.name === 'untouched').result,
    before.state.settings.find(item => item.name === 'untouched').result);
  assert.equal(invalid.vm.stateAfter.running, true, 'a settings fault does not reset program state');

  const recovered = scan(2_000, false, false, packet('recover', 3, 5, [
    change('enabled', 'Bool', true), change('gain', 'Number', 4),
    change('level', 'Percent', 50), change('duration', 'Duration', 3_000),
  ]));
  assert.deepEqual(recovered.frame, { scanId: 4, logicalTimeMs: 2_000 });
  assert.deepEqual(recovered.vm.safe, { run: true, permitted: true, gain_value: 4 });
  assert.equal(recovered.vm.stateAfter.running, true);
  assert.equal(runtime.contextSnapshot().state.settingsRevision, 4);

  const deadline = scan(3_000, false, false);
  assert.deepEqual(deadline.frame, { scanId: 5, logicalTimeMs: 3_000 });
  assert.equal(deadline.vm.safe.run, false,
    'elapsed timer retains its original start across settings success, fault and recovery');
  assert.equal(runtime.contextSnapshot().state.programFingerprint, fingerprint);
});

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import test from 'node:test';
import { compileSource } from '../tools/compile-source.mjs';
import { sha256Hex } from '../tools/sha256.mjs';
import { writeArtifact, restoreArtifactSourceMap } from '../tools/toolchain.mjs';
import { ControlRuntime } from '../runtimes/wasm/control-runtime.mjs';

const document = code => `# Exact import intent\n\n\`\`\`ghost\n${code}\n\`\`\`\n`;
const pin = (alias, locator, revision, text) => `import ${alias} from "${locator}" revision "${revision}" sha256 "${sha256Hex(text)}";`;
const leaf = document('control Leaf { input start: Bool; output pump: Bool; pump <- start; }');
const middle = document(`${pin('Leaf', './leaf.ghost.md', 'leaf-r7', leaf)}
control Middle { input start: Bool; output pump: Bool; instance inner: Leaf;
connect inner.start <- start; connect pump <- inner.pump; }`);
const source = document(`${pin('Middle', './lib/middle.ghost.md', 'middle-r4', middle)}
control Farm { input start: Bool; output pump: Bool; instance outer: Middle;
connect outer.start <- start; connect pump <- outer.pump; }`);
const documents = [
  { filename: 'lib/middle.ghost.md', revision: 'middle-r4', text: middle },
  { filename: 'lib/leaf.ghost.md', revision: 'leaf-r7', text: leaf },
];
const compile = (text = source, closure = documents) => compileSource(text, { filename: 'farm.ghost.md', sourceClosure: closure });

test('REF-06-011 exact transitive revision and digest closure survives artifact replay and native framed WASM execution', async t => {
  const owned = structuredClone(documents), before = structuredClone(owned);
  const artifact = await compile(source, owned);
  assert.deepEqual(owned, before, 'closure resolution must not rewrite caller sources or revisions');
  assert.deepEqual(artifact.sourceClosure.documents, [...documents].sort((a,b) => a.filename.localeCompare(b.filename))
    .map(item => ({ ...item, sha256: sha256Hex(item.text) })));
  assert.deepEqual([...artifact.sourceClosure.instances].sort((a,b) => a.instance.localeCompare(b.instance)), [
    { instance: 'outer', filename: 'lib/middle.ghost.md', definition: 'Middle' },
    { instance: 'outer.inner', filename: 'lib/leaf.ghost.md', definition: 'Leaf' },
  ]);
  assert.equal(artifact.sourceDocument.text, source);
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'ghostflow-pinned-closure-'));
  t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
  const modulePath = path.join(directory, 'farm.gfb'), tapePath = path.join(directory, 'frames.tsv');
  writeArtifact(artifact, modulePath);
  const map = JSON.parse(fs.readFileSync(`${modulePath}.map.json`, 'utf8'));
  assert.deepEqual(restoreArtifactSourceMap(map, artifact.bytes, { manifest: artifact.manifest }).sourceClosure, artifact.sourceClosure);
  const wasm = fs.readFileSync(new URL('../target/wasm32-unknown-unknown/release/ghostflow_wasm.wasm', import.meta.url));
  const runtime = await ControlRuntime.instantiateFramed(wasm, artifact);
  t.after(() => runtime.dispose());
  const frames = [], outcomes = [], dispatch = runtime.runtime.dispatch.bind(runtime.runtime);
  runtime.runtime.dispatch = frame => { frames.push(structuredClone(frame)); dispatch(frame); outcomes.push(structuredClone(runtime.runtime.outcome)); };
  for (const [nowMs, start] of [[0,false], [1,true], [2,false]]) runtime.step({ nowMs, inputs: { start } });
  fs.writeFileSync(tapePath, frames.map(frame => [frame.scanId, frame.logicalTimeMs,
    ...frame.inputs.flatMap(input => [input.name, input.type === 'Bool' ? 'b' : 'n', input.value])].join('\t')).join('\n') + '\n');
  const nativePath = fileURLToPath(new URL('../target/release/examples/scan_tape' + (process.platform === 'win32' ? '.exe' : ''), import.meta.url));
  const native = spawnSync(nativePath, [modulePath,tapePath], { encoding: 'utf8', timeout: 10_000 });
  assert.equal(native.status, 0, native.error?.message ?? native.stderr);
  const rows = native.stdout.trim().split('\n').map(JSON.parse);
  assert.ok(rows.every(row => row.accepted));
  assert.deepEqual(rows.map(row => row.outcome), outcomes, 'same pinned bytecode must produce complete native/WASM outcome parity');
  assert.deepEqual(outcomes.map(row => row.trace.safe), [{pump:false},{pump:true},{pump:false}]);
  for (const [field, change] of [
    ['revision', item => { item.revision = 'leaf-r8'; }],
    ['text', item => { item.text += '\nChanged authored rationale'; }],
    ['digest', item => { item.sha256 = '0'.repeat(64); }],
  ]) {
    const forged = structuredClone(map);
    change(forged.sourceClosure.documents.find(item => item.filename === 'lib/leaf.ghost.md'));
    assert.throws(() => restoreArtifactSourceMap(forged, artifact.bytes), /revision mismatch|digest mismatch|does not match canonical source/, field);
  }
});

test('REF-06-011 missing or floating transitive pins and revision or digest mismatches reject at their authored dependency', async () => {
  for (const [label, closure, pattern] of [
    ['missing leaf', documents.slice(0,1), /missing imported document .*leaf/],
    ['transitive revision', [documents[0], {...documents[1], revision:'leaf-r8'}], /import revision mismatch .*leaf/],
    ['transitive digest', [documents[0], {...documents[1], text: leaf + '\nChanged rationale'}], /import sha256 digest mismatch .*leaf/],
  ]) await assert.rejects(() => compile(source, closure), error => {
    assert.equal(error.diagnosticEnvelope.diagnostics[0].code, 'GF_IMPORT', label);
    assert.equal(error.filename, 'lib/middle.ghost.md', label);
    assert.equal(error.diagnosticEnvelope.requestSource.sha256, sha256Hex(source), label);
    assert.match(error.message, pattern, label);
    return true;
  });
  for (const [label, edit, pattern] of [
    ['missing revision', text => text.replace('revision "leaf-r7" ', ''), /requires an immutable revision/],
    ['floating revision', text => text.replace('"leaf-r7"', '"latest"'), /revision cannot be latest/],
    ['missing digest', text => text.replace(`sha256 "${sha256Hex(leaf)}"`, ''), /requires a SHA-256 digest/],
  ]) {
    const changed = edit(middle);
    const changedRoot = source.replace(sha256Hex(middle), sha256Hex(changed));
    await assert.rejects(() => compile(changedRoot, [{...documents[0], text:changed},documents[1]]), error => {
      assert.equal(error.filename, 'lib/middle.ghost.md', label);
      assert.match(error.message, pattern, label);
      return true;
    });
  }
});

test('REF-06-011 executable transitive import back edges reject as cycles before their circular digest mismatch', async () => {
  // A content-pinned cycle cannot have independently constructible mutually
  // consistent hashes. Its closing edge is nevertheless an explicit cycle,
  // and must be diagnosed before treating that edge as a mere stale digest.
  const b = document(`import A from "./a.ghost.md" revision "a-r1" sha256 "${'0'.repeat(64)}"; control B { output result: Bool; result <- true; }`);
  const a = document(`${pin('B','./b.ghost.md','b-r1',b)} control A { output result: Bool; result <- true; }`);
  const root = document(`${pin('A','./lib/a.ghost.md','a-r1',a)} control Farm { output result: Bool; result <- true; }`);
  await assert.rejects(() => compile(root,[{filename:'lib/a.ghost.md',revision:'a-r1',text:a},{filename:'lib/b.ghost.md',revision:'b-r1',text:b}]), error => {
    assert.equal(error.filename, 'lib/b.ghost.md');
    assert.equal(error.diagnosticEnvelope.diagnostics[0].code, 'GF_IMPORT');
    assert.match(error.message, /executable import cycle at \.\/a\.ghost\.md/);
    return true;
  });
});

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { compileControl } from '../tools/control.mjs';
import { extractLiterate } from '../tools/literate.mjs';
import { compileSource, restoreArtifactSourceMap, verifyArtifactSourceMap, writeArtifact } from '../tools/toolchain.mjs';

const filename = 'mapped.ghost.md';
const markdown = [
  '# A literate control',
  '',
  '설명과 prose는 실행되지 않으며 😄 그대로 보존된다.',
  '',
  '```ghost',
  '// Full-line comment survives compilation.',
  'control Mapped {',
  '  output pump: Bool; // trailing comment',
  '  pump <- false;',
  '}',
  '```',
  '',
  '```markdown',
  'This nonexecuting block is also part of the authored document.',
  '```',
  '',
].join('\r\n');

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

const traceableTimerControl = `control TraceableTimer {
  input running: Bool;
  state enabled: Bool = false;
  enabled' = running;
  timer age = elapsed(enabled);
  output pump, permit: Bool;
  pump <- enabled';
  permit <- running;
  require pump => permit;
  require !(pump && permit);
}`;
const traceableTimerDocument = `# Traceable timer

\`\`\`ghost
${traceableTimerControl}
\`\`\`
`;
const traceableTimerFilename = 'traceable-timer.ghost.md';

function artifactMap(result) {
  return {
    format: 'GhostFlow/source-map-v1',
    bytecodeSha256: result.manifest.bytecodeSha256,
    sourceDocument: result.sourceDocument,
    nodes: result.sourceMap,
    lines: result.extractionMap,
    traceMetadata: result.traceMetadata,
  };
}

test('schedule generated inputs preserve declaration bindings through artifact publication', async t => {
  const source = '# Schedule provenance\n\n```ghost\ncontrol Schedules {\n'
    + '  schedule dawn: Solar { timezone = "UTC"; latitude = 0; longitude = 0; at = sun`rise`; fallback = skip; }\n'
    + '  schedule slots: DailySlots<15min> { timezone = "UTC"; selected = [06:00]; }\n'
    + '  output pump: Bool;\n  pump <- dawn.due || slots.due;\n}\n```\n';
  const result = await compileSource(source, { filename: 'schedules.ghost.md' });
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'ghostflow-schedule-map-'));
  t.after(() => fs.rmSync(temporary, { recursive: true, force: true }));
  const artifact = path.join(temporary, 'schedules.gfb');
  writeArtifact(result, artifact);
  const map = JSON.parse(fs.readFileSync(`${artifact}.map.json`, 'utf8'));
  assert.deepEqual(verifyArtifactSourceMap(map, result.bytes), result.sourceDocument);
  const bindings = map.traceMetadata.bindings.filter(binding => binding.kind === 'schedule');
  assert.deepEqual(bindings.map(binding => binding.name), ['__gf_schedule_due_dawn', '__gf_schedule_due_slots']);
  for (const binding of bindings) {
    assert.deepEqual(binding.fields, ['inputs']);
    assert.equal(map.nodes.find(node => node.id === binding.nodeId)?.kind, 'schedule');
    const missing = clone(map);
    missing.traceMetadata.bindings = missing.traceMetadata.bindings.filter(item => item.nodeId !== binding.nodeId);
    assert.throws(() => verifyArtifactSourceMap(missing, result.bytes), /schedule binding count/);
  }
});

test('source-preserving map recovers the exact CRLF literate document', async () => {
  const extracted = extractLiterate(markdown, { filename });
  const direct = compileControl(extracted.code, { filename });
  const result = await compileSource(markdown, { filename });

  assert.equal(result.manifest.name, 'Mapped');
  assert.equal(result.manifest.bytecodeSha256, createHash('sha256').update(result.bytes).digest('hex'));
  assert.deepEqual(Object.keys(result.manifest).sort(), [
    'bytecodeSha256', 'configs', 'format', 'inputs', 'name', 'outputs', 'schedules', 'sensors', 'signals', 'timers',
  ].sort(), 'the existing control manifest remains unchanged except for its existing bytecode digest');
  assert.equal('sourceSha256' in result.manifest, false);
  assert.deepEqual(result.sourceMap.map(node => node.id), direct.sourceMap.map(node => node.id), 'node IDs are immutable across remapping');
  assert.deepEqual(result.sourceDocument, {
    format: 'GhostFlow/source-document-v1',
    kind: 'literate',
    filename,
    text: markdown,
    sha256: createHash('sha256').update(markdown).digest('hex'),
  });

  const output = result.sourceMap.find(node => node.kind === 'output');
  assert.deepEqual(
    { filename: output.filename, line: output.line, column: output.column },
    { filename, line: 8, column: 3 },
  );
  assert.deepEqual(
    { filename: output.extracted.filename, line: output.extracted.line, column: output.extracted.column },
    { filename, line: 3, column: 3 },
  );

  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'ghostflow-toolchain-'));
  try {
    const artifact = path.join(temporary, 'nested', 'mapped.gfb');
    writeArtifact(result, artifact);
    assert.deepEqual(fs.readFileSync(artifact), result.bytes);
    const manifest = JSON.parse(fs.readFileSync(`${artifact}.manifest.json`, 'utf8'));
    const sourceMap = JSON.parse(fs.readFileSync(`${artifact}.map.json`, 'utf8'));
    assert.deepEqual(manifest, result.manifest);
    assert.deepEqual(sourceMap.nodes, result.sourceMap);
    assert.deepEqual(sourceMap.lines, result.extractionMap);
    assert.equal(sourceMap.format, 'GhostFlow/source-map-v1');
    assert.equal(sourceMap.bytecodeSha256, result.manifest.bytecodeSha256);
    assert.deepEqual(
      verifyArtifactSourceMap(sourceMap, fs.readFileSync(artifact), { expectedSourceSha256: result.sourceDocument.sha256 }),
      result.sourceDocument,
    );
  } finally {
    fs.rmSync(temporary, { recursive: true, force: true });
  }
});

test('comment-only literate revisions retain GFB and node identity but change source identity', async () => {
  const original = await compileSource(markdown, { filename });
  for (const revised of [
    markdown.replace('설명과 prose는 실행되지 않으며 😄 그대로 보존된다.', '개정된 설명과 prose도 그대로 보존된다.'),
    markdown.replace('// Full-line comment survives compilation.', '// 개정된 주석\r\n// 추가된 설명'),
    markdown.replace('// trailing comment', '// 출력의 이유를 수정한 주석'),
  ]) {
    const changed = await compileSource(revised, { filename });
    assert.notEqual(changed.sourceDocument.sha256, original.sourceDocument.sha256);
    assert.deepEqual(changed.bytes, original.bytes);
    assert.deepEqual(changed.sourceMap.map(node => node.id), original.sourceMap.map(node => node.id));
    const changedMap = {
      format: 'GhostFlow/source-map-v1',
      bytecodeSha256: changed.manifest.bytecodeSha256,
      sourceDocument: changed.sourceDocument,
      nodes: changed.sourceMap,
      lines: changed.extractionMap,
    };
    assert.deepEqual(verifyArtifactSourceMap(changedMap, original.bytes), changed.sourceDocument);
    assert.throws(() => verifyArtifactSourceMap(changedMap, original.bytes, {
      expectedSourceSha256: original.sourceDocument.sha256,
    }), /expected revision/, 'identical bytecode must not hide a different document revision');
  }
});

